class Car {
  constructor(name) {
    this.name =
  name;

  }
  static hello() {
    return "Hello!!";

  }
}

const myCar = new Car("Ford");

// You can call 'hello()' on
  the Car Class:
document.getElementById("demo").innerHTML
  = Car.hello();

// But NOT on a Car Object:
// document.getElementById("demo").innerHTML
  = myCar.hello();
// this will raise an error.

class Car {
  constructor(name) {
    this.name =
  name;

  }
  static hello(x) {
    return "Hello " +
  x.name;

  }
}
const myCar = new Car("Ford");
document.getElementById("demo").innerHTML
  = Car.hello(myCar);
